import crypto from 'node:crypto';
import { z } from 'zod';

/**
 * CCare password rules:
 *  - generated by the system: exactly 8 characters, with at least one upper-case
 *    letter, one lower-case letter and one digit (sent to the staff phone by SMS)
 *  - chosen by the person (forgot password): 6–8 letters/digits, with at least
 *    one upper-case letter, one lower-case letter and one digit
 */
export const PASSWORD_MIN = 6;
export const PASSWORD_MAX = 8;

// No look-alikes (O/0, I/l/1) so an SMS password is easy to type.
const UPPER = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
const LOWER = 'abcdefghijkmnpqrstuvwxyz';
const DIGIT = '23456789';
const pick = (set) => set[crypto.randomInt(0, set.length)];

/** A random 8-character password with at least one upper, one lower and one digit. */
export function generatePassword(length = PASSWORD_MAX) {
  const all = UPPER + LOWER + DIGIT;
  const chars = [pick(UPPER), pick(LOWER), pick(DIGIT)];
  while (chars.length < length) chars.push(pick(all));
  // Fisher–Yates shuffle so the required characters are not always first.
  for (let i = chars.length - 1; i > 0; i -= 1) {
    const j = crypto.randomInt(0, i + 1);
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return chars.join('');
}

/** The rule for a password a person sets themselves. */
export const passwordRule = z
  .string()
  .min(PASSWORD_MIN, `Password must be ${PASSWORD_MIN}–${PASSWORD_MAX} characters`)
  .max(PASSWORD_MAX, `Password must be at most ${PASSWORD_MAX} characters`)
  .regex(/^[A-Za-z0-9]+$/, 'Use only letters and digits')
  .regex(/[A-Z]/, 'Add at least one upper-case letter (A–Z)')
  .regex(/[a-z]/, 'Add at least one lower-case letter (a–z)')
  .regex(/[0-9]/, 'Add at least one digit (0–9)');
